// Define alias types directly from the global ambient namespace generated by Spatie
export type DashboardPermissions =
    App.Enums.Authorization.Permissions.DashboardPermissions;
export type GeneralPermissions =
    App.Enums.Authorization.Permissions.GeneralPermissions;
export type ModulePermissions =
    App.Enums.Authorization.Permissions.ModulePermissions;
export type RolePermissions =
    App.Enums.Authorization.Permissions.RolePermissions;
export type UserPermissions =
    App.Enums.Authorization.Permissions.UserPermissions;

// Composite union of all generated backend permission enums
export type AppPermission =
    | DashboardPermissions
    | GeneralPermissions
    | ModulePermissions
    | RolePermissions
    | UserPermissions;

// Loose string fallback without triggering no-redundant-type-constituents
export type LoosePermission = AppPermission | (string & {});

// Helper type for props or functions that accept single permissions or array checking
export type PermissionCheck = LoosePermission | LoosePermission[];
